def convert_tensor_to_value(metrics):
    for key, value in metrics.items():
        if hasattr(value, "item"):  
            metrics[key] = value.item()  
        elif isinstance(value, dict):  
            metrics[key] = convert_tensor_to_value(value)
    return metrics





class SinusoidsEmbedding(nn.Module):
    def __init__(self, n_frequencies = 10, n_space = 3):
        super().__init__()
        self.n_frequencies = n_frequencies
        self.n_space = n_space
        self.frequencies = 2 * math.pi * torch.arange(self.n_frequencies)
        self.dim = self.n_frequencies * 2 * self.n_space

    def forward(self, x):
        emb = x.unsqueeze(-1) * self.frequencies[None, None, :].to(x.device)
        emb = emb.reshape(-1, self.n_frequencies * self.n_space)
        emb = torch.cat((emb.sin(), emb.cos()), dim=-1)
        return emb


def get_env(env_name: str, default: Optional[str] = None) -> str:
    """
    Safely read an environment variable.
    Raises errors if it is not defined or it is empty.

    :param env_name: the name of the environment variable
    :param default: the default (optional) value for the environment variable

    :return: the value of the environment variable
    """
    if env_name not in os.environ:
        if default is None:
            raise KeyError(
                f"{env_name} not defined and no default value is present!")
        return default

    env_value: str = os.environ[env_name]
    if not env_value:
        if default is None:
            raise ValueError(
                f"{env_name} has yet to be configured and no default value is present!"
            )
        return default

    return env_value


def load_envs(env_file: Optional[str] = None) -> None:
    """
    Load all the environment variables defined in the `env_file`.
    This is equivalent to `. env_file` in bash.

    It is possible to define all the system specific variables in the `env_file`.

    :param env_file: the file that defines the environment variables to use. If None
                     it searches for a `.env` file in the project.
    """
    dotenv.load_dotenv(dotenv_path=env_file, override=True)


STATS_KEY: str = "stats"


# Adapted from https://github.com/hobogalaxy/lightning-hydra-template/blob/6bf03035107e12568e3e576e82f83da0f91d6a11/src/utils/template_utils.py#L125
def log_hyperparameters(
    cfg: DictConfig,
    model: pl.LightningModule,
    trainer: pl.Trainer,
) -> None:
    """This method controls which parameters from Hydra config are saved by Lightning loggers.
    Additionally saves:
        - sizes of train, val, test dataset
        - number of trainable model parameters
    Args:
        cfg (DictConfig): [description]
        model (pl.LightningModule): [description]
        trainer (pl.Trainer): [description]
    """
    hparams = OmegaConf.to_container(cfg, resolve=True)

    # save number of model parameters
    hparams[f"{STATS_KEY}/params_total"] = sum(p.numel()
                                               for p in model.parameters())
    hparams[f"{STATS_KEY}/params_trainable"] = sum(
        p.numel() for p in model.parameters() if p.requires_grad
    )
    hparams[f"{STATS_KEY}/params_not_trainable"] = sum(
        p.numel() for p in model.parameters() if not p.requires_grad
    )

    # send hparams to all loggers
    trainer.logger.log_hyperparams(hparams)

    # disable logging any more hyperparameters for all loggers
    # (this is just a trick to prevent trainer from logging hparams of model, since we already did that above)
    trainer.logger.log_hyperparams = lambda params: None


# Load environment variables (optional)
# - If `.env` exists, it will be loaded.
# - If not, we fall back to sane defaults so the repo works out-of-the-box.
load_envs()

# Infer project root if not provided
_DEFAULT_PROJECT_ROOT = Path(__file__).resolve().parents[2]
PROJECT_ROOT: Path = Path(os.environ.get("PROJECT_ROOT", str(_DEFAULT_PROJECT_ROOT))).expanduser().resolve()
os.environ.setdefault("PROJECT_ROOT", str(PROJECT_ROOT))

assert PROJECT_ROOT.exists(), (
    "PROJECT_ROOT does not exist. Set PROJECT_ROOT in your environment or in a .env file."
)

# Default output dirs (can be overridden by env vars)
HYDRA_JOBS: Path = Path(os.environ.get("HYDRA_JOBS", str(PROJECT_ROOT / "outputs" / "hydra"))).expanduser().resolve()
WANDB_DIR: Path = Path(os.environ.get("WANDB_DIR", str(PROJECT_ROOT / "outputs" / "wandb"))).expanduser().resolve()
os.environ.setdefault("HYDRA_JOBS", str(HYDRA_JOBS))
os.environ.setdefault("WANDB_DIR", str(WANDB_DIR))

# Create output dirs lazily to avoid surprises when importing
HYDRA_JOBS.mkdir(parents=True, exist_ok=True)
WANDB_DIR.mkdir(parents=True, exist_ok=True)

# Set the cwd to the project root
os.chdir(PROJECT_ROOT)


